231	// pathFooterHeight is the Path footer in every state: the target bar (2), the
232	// tab row, a blank line and the info line (Rule 124).
233	const pathFooterHeight = 5
234	
235	// GetFooterHeight implements FooterView — tab bar + empty + info + ports filter bar when visible (Rule 124)
236	func (m *Model) GetFooterHeight() int {
237		if m.activeTab == tabPath {
238			return pathFooterHeight
239		}
240		if m.activeTab == tabPorts {
241			return 3 + m.portsModel.table.FilterBar().ExtraHeight()
242		}
243		if m.inTrace() {
244			return 3 // no filter bar on the sub-level (Rule 124)
245		}
246		if m.activeTab == tabDiagnostics {
247			return 3 + m.filterBar.ExtraHeight()
248		}
249		if m.activeTab == tabInterfaces {
250			return 3 + m.interfacesModel.table.FilterBar().ExtraHeight()
251		}
252		if m.activeTab == tabForward {
253			return 3 + m.forwardModel.table.FilterBar().ExtraHeight()
254		}
255		return 3
256	}
257	
258	// RenderFooter implements FooterView
259	func (m *Model) RenderFooter(width int) string {
260		var parts []string
261	
262		// The active tab's filter bar renders above the tab bar when visible; on
263		// Path the target field takes that slot in every state.
264		switch {
265		case m.activeTab == tabPath:
266			parts = append(parts, m.pathModel.barView(width))
267		case m.activeTab == tabPorts && m.portsModel.table.FilterBar().IsVisible():
268			parts = append(parts, m.portsModel.table.FilterBar().View())
269		case m.activeTab == tabDiagnostics && !m.inTrace() && m.filterBar.IsVisible():
270			parts = append(parts, m.filterBar.View())
271		case m.activeTab == tabInterfaces && m.interfacesModel.table.FilterBar().IsVisible():
272			parts = append(parts, m.interfacesModel.table.FilterBar().View())
273		case m.activeTab == tabForward && m.forwardModel.table.FilterBar().IsVisible():
274			parts = append(parts, m.forwardModel.table.FilterBar().View())
275		}
276	
277		tabs := theme.RenderTabs([]theme.TabItem{
278			{Label: "Diagnostics"},
279			{Label: "Ports"},
280			{Label: "Interfaces"},
281			{Label: "Forward"},
282			{Label: "Path"},
283		}, m.activeTab)
284		tabBar := theme.PadWithBg(theme.Bg(" ")+tabs, width)
285	
286		// The message belongs to the tab that raised it: each sub-model keeps its
287		// own, so switching away does not carry one tab's notice onto another.
288		footer, status := m.activeFooter()
289		parts = append(parts, tabBar, theme.EmptyLineBg(width), footer.View(width, status))
290		return strings.Join(parts, "\n")
291	}
292	
293	// activeFooter resolves the message line of whichever tab is on screen, and the
294	// status that tab derives on every frame.
295	func (m *Model) activeFooter() (*components.FooterMessage, components.Status) {
296		switch m.activeTab {
297		case tabPorts:
298			return &m.portsModel.footer, m.portsModel.statusLine()
299		case tabInterfaces:
300			return &m.interfacesModel.footer, m.interfacesModel.statusLine()
301		case tabForward:
302			return &m.forwardModel.footer, m.forwardModel.status()
303		case tabPath:
304			return &m.pathModel.footer, m.pathModel.statusLine()
305		}
306		if m.state == StateTrace {
307			return &m.pathModel.footer, m.pathModel.statusLine()
308		}
309		return &m.footer, m.statusLine()
310	}
311	
312	// statusLine is what the diagnostics tab derives on every frame: a progress
313	// label while the pipeline walks, and nothing once it has an answer. It is a
314	// status rather than a footer message because it is a state, not an event —
315	// a message expires after three seconds and a run outlives that (Rule 128).
316	func (m *Model) statusLine() components.Status {
317		if m.state == StateRunning {
318			return components.Status{Text: m.progressLabel(), Activity: true}
319		}
320		if m.state == StateInput {
321			if st := m.traceValidation.Status(); st.Text != "" {
322				return st
323			}
324		}
325		if m.state == StateInput {
326			if a := m.traceable(); !a.Enabled() {
327				return components.Status{Text: a.Reason, Level: components.LevelWarning}
328			}
329		}
330		return components.Status{}
331	}
