333	// GetHelpContent implements help.Provider
334	func (m *Model) GetHelpContent() help.Content {
335		return help.Content{
336			Title:       "Network",
337			Description: "Five-tab view: check whether a host is reachable and its certificate chain sound (Diagnostics), monitor live ports (Ports), inspect this machine's network interfaces (Interfaces), or redirect a local port to a host:port, or give a service a name (Forward), or trace the hops a packet takes to a host (Path).",
338			KeyBindings: []help.KeyBinding{
339				// Tab navigation
340				{Key: "tab / shift+tab", Description: "Cycle between the Diagnostics, Ports, Interfaces, Forward and Path tabs"},
341				// Diagnostics
342				{Key: "↑ / ↓", Description: "Navigate between the fields and the Run Diagnostics and Trace Path buttons (Diagnostics tab)"},
343				{Key: "enter (form)", Description: "Run the checks against the target, from any field or the Run Diagnostics button"},
344				{Key: "esc (running)", Description: "Cancel the run and keep what completed"},
345				{Key: "enter (results)", Description: "Explain the selected check"},
346				{Key: "p", Description: "Show problems only / show every check (Diagnostics tab)"},
347				{Key: "/", Description: "Search checks by name or observation (Diagnostics tab)"},
348				{Key: keymap.Diagnose + " (results)", Description: "Trace the path to the target: on the Local route row, opens the trace sub-level on the host, ready to start; nothing is sent until enter; greyed out on a platform that cannot trace or a target the trace refuses, with the reason in the footer (Diagnostics tab)"},
349				{Key: "ctrl+r", Description: "Run the checks again"},
350				{Key: "esc (results)", Description: "Back to the target form, or back to wherever this run was opened from (e.g. status's H) when it was opened prefilled"},
351				{Key: keymap.New + " (results)", Description: "Start a new diagnostic — always resets to the form, even when esc there means \"go back\""},
352				{Key: "esc (details)", Description: "Back to the checks"},
353				{Key: "pgup / pgdown", Description: "Scroll half page up / down"},
354				// Ports tab
355				{Key: "t", Description: "Toggle TCP filter — cumulative with u (Ports tab)"},
356				{Key: "u", Description: "Toggle UDP filter — cumulative with t (Ports tab)"},
357				{Key: "l", Description: "Toggle LISTEN state filter — cumulative with e (Ports tab)"},
358				{Key: "e", Description: "Toggle ESTAB state filter — cumulative with l (Ports tab)"},
359				{Key: "n", Description: "Toggle numeric addresses / reverse-DNS host names (Ports tab)"},
360				{Key: "z", Description: "Reset all active filters (Ports tab)"},
361				{Key: "/", Description: "Search ports by address, process or PID (Ports tab)"},
362				{Key: "space (Ports)", Description: "Pause / resume auto-refresh (Ports tab)"},
363				{Key: keymap.Kill, Description: "Send SIGKILL to the selected process, after confirmation (Ports tab)"},
364				// Interfaces tab
365				{Key: "/", Description: "Search interfaces by name, MAC or address (Interfaces tab)"},
366				{Key: ".", Description: "Cycle the sort column (Interfaces tab)"},
367				{Key: "ctrl+r", Description: "Re-read the interfaces (Interfaces tab)"},
368				// Forward tab
369				{Key: keymap.New, Description: "Open a new forward — TCP, or a named HTTP route (Forward tab)"},
370				{Key: "space", Description: "Pause the selected forward, or resume a paused or unbound one (Forward tab)"},
371				{Key: keymap.Kill, Description: "Delete the selected forward, after confirmation (Forward tab)"},
372				{Key: "/", Description: "Search forwards by port or target (Forward tab)"},
373				{Key: ".", Description: "Cycle the sort column (Forward tab)"},
374				// Path tab
375				{Key: "enter (Path)", Description: "Trace the path to the target typed in the field, or trace again once a trace is done (Path tab)"},
376				{Key: "esc (Path, running)", Description: "Cancel the trace and keep the hops already seen (Path tab)"},
377				{Key: "esc (Path, done)", Description: "Edit the target again, keeping its value (Path tab)"},
378				{Key: "enter (Trace Path button)", Description: "Trace the path to the form's target in a sub-level of the Diagnostics tab, Network › Path › target; Port and DNS Server are ignored by the trace (an info line says so); greyed out on a platform that cannot trace, with the reason in the footer (Diagnostics tab)"},
379				{Key: "esc (trace)", Description: "Cancel a running trace; once it ended or before it started, go back to the form or the results it was opened from, with everything kept (Diagnostics tab)"},
380				{Key: "↑ / ↓ / pgup / pgdown / home / end (trace)", Description: "Move in the hop table; every other key is ignored there except tab, which switches tab (Diagnostics tab)"},
381				{Key: "enter (trace)", Description: "Start the trace, or trace again once it ended (Diagnostics tab)"},
382				{Key: "ctrl+o (trace)", Description: "Choose where the trace starts: this machine or a running container; ↑↓ to move, enter to choose (it starts nothing), esc to close (Diagnostics tab)"},
383				{Key: "ctrl+o (Path)", Description: "Choose where the trace starts: this machine or a running container; ↑↓ to move, enter to choose, esc to close (Path tab)"},
384			},
385			Sections: []help.Section{
386				{
387					Title: "Diagnostics Tab — What it asks",
388					Body: "One target, one run. The checks follow from the target and from what has " +
389						"already failed, so there is nothing to select.\n\n" +
390						"DNS resolution     - the name, against the resolver your own traffic uses\n" +
391						"Reverse DNS        - the name an address publishes (literal targets only)\n" +
392						"Local route        - which interface carries this target, and from which address\n" +
393						"ICMP echo          - reachability; a filtered echo is a warning, never a failure\n" +
394						"TCP connect        - the port you named, and the answer that decides reachability\n" +
395						"TLS handshake      - whether the port speaks TLS at all\n" +
396						"Certificate chain  - verified against this machine's store, intermediates included\n" +
397						"Hostname match     - whether the certificate names the host you dialled\n" +
398						"Certificate expiry - the validity window, in days\n" +
399						"TLS version        - the negotiated protocol version\n" +
400						"HTTP response      - whether the service answers, over the scheme actually spoken",
401				},
402				{
403					Title: "Diagnostics Tab — Reading the verdicts",
404					Body: "OK      - the objective is met\n" +
405						"WARN    - met, but something is off: a certificate near expiry, a deprecated\n" +
406						"          version, a chain that verifies here and will not elsewhere\n" +
407						"FAIL    - the objective is not met\n" +
408						"N/A     - no meaning for this target, or blocked by a check above it\n" +
409						"UNKNOWN - the check could not look, which is not the same as a pass\n\n" +
410						"A stage whose dependency failed does not run: its checks come back N/A naming " +
411						"what blocked them, so a broken run reads as one failure and a named point of " +
412						"rupture rather than as ten red rows.\n\n" +
413						"Press enter on any row for what it means and what to do about it.",
414				},
415				indicator.Legend(),
416				{
417					Title: "Ports Tab — How it works",
418					Body: "Reads this machine's TCP and UDP sockets every 2 seconds, in this process — no " +
419						"container, no Docker. Shows the owning process name and PID where the system will " +
420						"name one. K terminates that process, after a confirmation, with the rights DevDesk " +
421						"itself has: another user's process or a service comes back refused rather than " +
422						"silently killed elsewhere.\n\n" +
423						"n toggles reverse DNS on the addresses. Host names only — port numbers stay " +
424						"numeric, because a service name would be DevDesk's guess and not the system's.\n\n" +
425						"While K is killing a process, the dot on its sockets (" + indicator.Glyph(indicator.Running, true) +
426						") is lit and the footer names the kill.",
427				},
428				{
429					Title: "Forward Tab — How it works",
430					Body: "Redirects traffic to a host:port, inside this process — no privilege, " +
431						"no container, nothing written to a system file. Use it to reach a port nothing " +
432						"published: a container's EXPOSEd port, or a service on another machine.\n\n" +
433						"N opens a form with a Type field, changed with ← →. TCP redirects a local port " +
434						"to a host:port. HTTP gives the target a name instead of a port: fill in Name " +
435						"and Target, and http://<name>:<proxy port> reaches it.\n\n" +
436						"A name must end in .localhost, such as api.localhost — nothing else is " +
437						"accepted. That suffix is reserved for this machine, so it needs no DNS entry and " +
438						"no privilege; any other name would not resolve. Every named route is served on " +
439						"the same port, network.proxy_port (8080 by default, in the network tab of the " +
440						"configuration), and the request's Host header picks the target — so " +
441						"http://api.localhost:8080 and http://app.localhost:8080 are two services on one " +
442						"port. The port stays in the URL because 80 is privileged. It is HTTP only: " +
443						"https would need a certificate your browser trusts. A name that is not known " +
444						"gets a page listing the ones that are.\n\n" +
445						"Everything listens on 127.0.0.1 only, so it is available to this machine and " +
446						"not to the network — a service kept off the LAN stays off it. A TCP forward's " +
447						"local port has to be 1024 or above, and cannot be the proxy's: anything below " +
448						"needs privileges DevDesk does not ask for, and there is no unprivileged way " +
449						"around that on Linux or macOS.\n\n" +
450						"The target is dialled once before the port is bound, so an address that answers " +
451						"nothing is refused immediately instead of failing later at the first client. A " +
452						"container's own address is reachable from the host on native Linux; under " +
453						"Docker Desktop it lives in the virtual machine and does not route out of it.\n\n" +
454						"Forwards are saved in ~/.devdesk/forwards.yaml and reopened when DevDesk " +
455						"starts. They survive a context switch — a local port pointed at a host:port " +
456						"belongs to no context — but the listener itself cannot outlive the process, so " +
457						"what comes back is the list, bound again.\n\n" +
458						"A forward that cannot be bound at launch — its port is taken, or its target is " +
459						"not up yet — is not deleted. Its row reads unbound, the last error says why, and " +
460						"space tries again. Space also pauses a live forward: the port is released and the " +
461						"row stays, paused, until you resume it. K deletes a forward for good, and asks " +
462						"first.",
463				},
464				{
465					Title: "Path Tab — How it works",
466					Body: "Traces the hops between this machine and a target, in this process — no " +
467						"container, no traceroute binary. Native Linux and WSL2 only: on macOS, Windows and WSL1 the tab says so " +
468						"and enter and ctrl+o are greyed out. IPv4 only: a host name is resolved to its IPv4 address. " +
469						"The column starts on this machine: the interface the target's traffic leaves by, " +
470						"with its source address, and the gateway, read from this machine's routing table, " +
471						"then the hops. Under WSL2 the source row names the WSL2 VM, and in NAT mode the " +
472						"first hop through the virtual switch is labelled Windows host.\n\n" +
473						"Type a host name or an IPv4 address, and press enter; a port is refused because " +
474						"the trace probes a host, not a service. Each hop is a UDP datagram sent to UDP " +
475						"port 33435 with a growing time-to-live; the router that drops it answers, and the " +
476						"table fills in as the answers come. No connection is made. Nothing is sent before you " +
477						"press enter.\n\n" +
478						"A silent hop is not a failure: many routers do not answer these probes, so the row " +
479						"reads silent and the trace goes on. The header says how a trace ended.\n\n" +
480						"When the target never answers, the silent hops at the end fold into one row, " +
481						"no response beyond hop N, and the last hop that answered reads last to answer. " +
482						"When this machine has no route to the target, the interface row reads no route " +
483						"and nothing is sent; undetermined means the routing table could not be read, " +
484						"which says nothing either way. DevDesk shows only what came back: it does not " +
485						"say why the rest stayed silent.\n\n" +
486						"ctrl+o opens Trace from: this machine, or a running container (Docker Engine on " +
487						"Linux only). The column then starts with the container, its network and the " +
488						"gateway it uses, and a row says the probes still leave from this machine: " +
489						"nothing runs inside the container.\n\n" +
490						"Docker Desktop and podman are not offered. With no running container, only this " +
491						"machine is offered. Reading the engine (ps, info, inspect) starts nothing. An " +
492						"engine reached through DOCKER_HOST or a remote context is not detected as remote: " +
493						"it can show another machine's network, and the trace still leaves from this machine.\n\n" +
494						"The bridge row appears only when this machine has the interface of the container's " +
495						"network bridge, read on this machine; otherwise no bridge is shown. A remote engine " +
496						"whose network is also called docker0 can match this machine's interface by name.\n\n" +
497						"When the container's bridge is not on this machine, the engine row reads " +
498						"internal path not visible (location unknown): the engine may run in a VM, remote " +
499						"or rootless, and DevDesk does not guess. When it cannot check, the row reads " +
500						"undetermined (bridge not verified). The hops are traced from this machine (the " +
501						"host, or the WSL VM when DevDesk runs under WSL); DevDesk cannot see inside the " +
502						"engine's VM.",
503				},
504				{
505					Title: "Interfaces Tab — How it works",
506					Body: "Lists this machine's network interfaces, read in this process — no container, " +
507						"no Docker. Name, state, MTU, hardware address, error counters and every address " +
508						"the interface carries. ctrl+r re-reads them.\n\n" +
509						"A dash is not a zero. RX err and TX err show a dash when the counters could not " +
510						"be read at all, which is a different thing from an interface that has dropped " +
511						"nothing; MTU shows one where the platform reports no figure, as Windows does " +
512						"for its loopback.\n\n" +
513						"This was the Topology tab. Its routing table, ARP cache and firewall summary " +
514						"were read by running ip and iptables in a container on the Docker Desktop VM, " +
515						"so they described the VM and not this machine. Nothing portable produces them, " +
516						"so they were removed rather than translated — and the route question moved to " +
517						"the Diagnostics tab, where it is asked about a target: the Local route check " +
518						"names the interface your traffic to that host actually leaves by.",
519				},
520				{
521					Title: "Where the checks run",
522					Body: "Everything here runs in this process, on this machine's network stack: the " +
523						"diagnostic checks, the socket table, the interfaces and the path trace alike. They answer for " +
524						"the resolver, the routing table, the sockets and the VPN you are actually on, " +
525						"and nothing needs Docker.\n\n" +
526						"The route trace used to be the exception. It ran traceroute in a container " +
527						"started with --network host, which on Docker Desktop is the Linux VM's " +
528						"namespace — so it traced the path from the VM and not from here, and the two " +
529						"are not the same network. It was removed rather than kept with a caveat.\n\n" +
530						"The trace is back, in this process: the Path tab sends its own probes from this " +
531						"machine's network stack, so it answers for the network you are actually on. The " +
532						"Local route check still names the interface and source address your traffic to a " +
533						"target leaves by — the split-tunnel answer, read from this machine.",
534				},
535			},
536		}
537	}
538

file.content:
package netdiag

import (
	"strings"

	"charm.land/lipgloss/v2"

	"github.com/anthnel/devdesk/internal/netcheck"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/help"
	"github.com/anthnel/devdesk/internal/ui/indicator"
	"github.com/anthnel/devdesk/internal/ui/keymap"
	"github.com/anthnel/devdesk/internal/ui/shortcut"
	"github.com/anthnel/devdesk/internal/ui/theme"
)

// GetTitle implements HeaderView
func (m *Model) GetTitle() string {
	base := theme.IconNetwork + " Network"
	if m.activeTab == tabDiagnostics && m.state == StateTrace {
		return m.traceTitle(base)
	}
	if m.state == StateDetails {
		if label := m.selected.Title; label != "" {
			return base + titleTrailStyle().Render(" "+theme.IconChevronRight+" "+label)
		}
	}
	return base
}

// GetIcon implements HeaderView
func (m *Model) GetIcon() string {
	return theme.IconNetwork
}

// GetShortcuts implements HeaderView
func (m *Model) GetShortcuts() shortcut.Shortcuts {
	tabShortcuts := shortcut.Shortcuts{
		{Key: "tab", Description: "Switch tab"},
	}

	if m.activeTab == tabPath {
		return m.pathModel.shortcuts()
	}

	if m.activeTab == tabInterfaces {
		// A read in flight greys the table's keys rather than removing them:
		// the tab is the same screen either side of a refresh, and a column
		// that empties and refills on every ctrl+r is the flicker Rule 130 is
		// about. ctrl+r stays lit — asking again is exactly what still applies.
		loading := m.interfacesModel.loading
		return append(tabShortcuts, shortcut.Shortcuts{
			{Key: "ctrl+r", Description: "Refresh"},
			{Key: "/", Description: "Filter", Disabled: loading},
			{Key: ".", Description: "Sort", Disabled: loading},
			{Key: "?", Description: "Help"},
		}...)
	}

	if m.activeTab == tabForward {
		if m.forwardModel.form != nil {
			// A form is a mode, so the whole list is replaced rather than
			// greyed (Rule 130): greying N and K here would show the union of
			// two vocabularies.
			return shortcut.Shortcuts{
				// ←→ only cycles the type, so it greys elsewhere (Rule 130).
				{Key: "←→", Description: "Change type", Disabled: !m.forwardModel.form.TypeFocused()},
				{Key: "enter", Description: "Open the forward"},
				{Key: "esc", Description: "Cancel"},
			}
		}
		if m.forwardModel.table.FilterBar().InEditMode() {
			return shortcut.Shortcuts{
				{Key: "enter/esc", Description: "Confirm / Cancel search"},
			}
		}
		return append(tabShortcuts, shortcut.Shortcuts{
			{Key: keymap.New, Description: "New forward"},
			// Nothing to pause, resume or delete on an empty table (Rule 130).
			{Key: "space", Description: m.forwardModel.toggleLabel(), Disabled: !m.forwardModel.switchable().Enabled()},
			{Key: keymap.Kill, Description: "Delete forward", Disabled: !m.forwardModel.closable().Enabled()},
			{Key: "/", Description: "Search"},
			{Key: ".", Description: "Sort"},
			{Key: "?", Description: "Help"},
		}...)
	}

	if m.activeTab == tabPorts {
		if m.portsModel.table.FilterBar().InEditMode() {
			return shortcut.Shortcuts{
				{Key: "enter/esc", Description: "Confirm / Cancel search"},
			}
		}
		sc := shortcut.Shortcuts{
			{Key: "t", Description: "Toggle TCP"},
			{Key: "u", Description: "Toggle UDP"},
			{Key: "l", Description: "Toggle LISTEN"},
			{Key: "e", Description: "Toggle ESTAB"},
			{Key: "n", Description: "Toggle numeric"},
			{Key: "z", Description: "Reset filters"},
			{Key: "/", Description: "Search"},
			{Key: "space", Description: "Pause/Resume"},
			// A socket the system declines to attribute carries no PID, so
			// there is nothing to signal (Rule 130).
			{Key: keymap.Kill, Description: "Kill process", Disabled: !m.portsModel.killable().Enabled()},
			{Key: "?", Description: "Help"},
		}
		return append(tabShortcuts, sc...)
	}

	switch m.state {
	case StateTrace:
		return m.traceShortcuts()
	case StateInput:
		enter := shortcut.Shortcut{Key: "enter", Description: "Run the checks"}
		if m.focusedField == fieldTraceButton {
			enter = shortcut.Shortcut{Key: "enter", Description: "Trace the path", Disabled: !m.traceable().Enabled()}
		}
		return append(tabShortcuts, shortcut.Shortcuts{
			enter,
			{Key: "?", Description: "Help"},
		}...)
	case StateRunning:
		return shortcut.Shortcuts{
			{Key: "esc", Description: "Cancel and keep what completed"},
		}
	case StateResults:
		if m.filterBar.InEditMode() {
			return shortcut.Shortcuts{
				{Key: "enter/esc", Description: "Confirm / Cancel search"},
			}
		}
		sc := shortcut.Shortcuts{
			{Key: "enter", Description: "Explain the check"},
		}
		label := "Show problems only"
		if m.filterBar.IsTokenActive(problemsToken) {
			label = "Show every check"
		}
		escLabel := "New diagnostic"
		if m.OriginView != "" {
			escLabel = "Go back"
		}
		sc = append(sc,
			shortcut.Shortcut{Key: "p", Description: label},
			shortcut.Shortcut{Key: "/", Description: "Search"},
			shortcut.Shortcut{Key: keymap.Diagnose, Description: "Trace the path", Disabled: !m.pathFromRoute().Enabled()},
			shortcut.Shortcut{Key: "ctrl+r", Description: "Run again"},
			shortcut.Shortcut{Key: "esc", Description: escLabel},
		)
		if m.OriginView != "" {
			// Otherwise esc already reads "New diagnostic" and does exactly
			// this — advertising both here would just say the same thing
			// twice (Rule 138). With an origin, esc means "go back" instead,
			// so this is the only key left that starts a fresh target.
			sc = append(sc, shortcut.Shortcut{Key: keymap.New, Description: "New diagnostic"})
		}
		sc = append(sc, shortcut.Shortcut{Key: "?", Description: "Help"})
		return append(tabShortcuts, sc...)
	case StateDetails:
		return shortcut.Shortcuts{
			{Key: "esc", Description: "Go back to the checks"},
		}
	}
	return tabShortcuts
}

// GetHeaderInfo implements HeaderView.
//
// The verdict is the one line worth spending: it is the answer to the question
// the view exists for, and reading it off ten rows is what the header is
// supposed to save. It appears only once there is a run to summarise.
func (m *Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
	info := []shortcut.HeaderInfo{
		{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
	}
	if m.activeTab == tabPath {
		return append(info, m.pathModel.headerInfo()...)
	}
	if m.activeTab == tabInterfaces {
		return append(info, shortcut.HeaderInfo{
			Key:   "Interfaces",
			Value: m.interfacesModel.summaryLine(),
			Style: theme.HeaderValueStyle,
		})
	}
	if m.activeTab == tabPorts {
		return append(info, shortcut.HeaderInfo{
			Key:   "Ports",
			Value: m.portsModel.summaryLine(),
			Style: theme.HeaderValueStyle,
		})
	}
	if m.activeTab == tabForward {
		return append(info, shortcut.HeaderInfo{
			Key:   "Forwards",
			Value: m.forwardModel.summaryLine(),
			Style: theme.HeaderValueStyle,
		})
	}
	if m.state == StateTrace {
		return append(info, m.pathModel.headerInfo()...)
	}
	if m.activeTab != tabDiagnostics || m.state == StateInput {
		return info
	}
	if len(m.results.All()) == 0 {
		return info
	}
	return append(info, shortcut.HeaderInfo{
		Key:   "Verdict",
		Value: m.verdict.String(),
		Style: verdictHeaderStyle(m.verdict),
	})
}

// verdictHeaderStyle colours the headline the way the table colours a cell.
func verdictHeaderStyle(v netcheck.Verdict) lipgloss.Style {
	switch v {
	case netcheck.Fail:
		return theme.SeverityTextStyle("CRITICAL")
	case netcheck.Warn:
		return theme.SeverityTextStyle("MEDIUM")
	case netcheck.OK:
		return theme.StatusOKStyle
	default:
		return theme.DimStyle
	}
}

// pathFooterHeight is the Path footer in every state: the target bar (2), the
// tab row, a blank line and the info line (Rule 124).
const pathFooterHeight = 5

// GetFooterHeight implements FooterView — tab bar + empty + info + ports filter bar when visible (Rule 124)
func (m *Model) GetFooterHeight() int {
	if m.activeTab == tabPath {
		return pathFooterHeight
	}
	if m.activeTab == tabPorts {
		return 3 + m.portsModel.table.FilterBar().ExtraHeight()
	}
	if m.inTrace() {
		return 3 // no filter bar on the sub-level (Rule 124)
	}
	if m.activeTab == tabDiagnostics {
		return 3 + m.filterBar.ExtraHeight()
	}
	if m.activeTab == tabInterfaces {
		return 3 + m.interfacesModel.table.FilterBar().ExtraHeight()
	}
	if m.activeTab == tabForward {
		return 3 + m.forwardModel.table.FilterBar().ExtraHeight()
	}
	return 3
}

// RenderFooter implements FooterView
func (m *Model) RenderFooter(width int) string {
	var parts []string

	// The active tab's filter bar renders above the tab bar when visible; on
	// Path the target field takes that slot in every state.
	switch {
	case m.activeTab == tabPath:
		parts = append(parts, m.pathModel.barView(width))
	case m.activeTab == tabPorts && m.portsModel.table.FilterBar().IsVisible():
		parts = append(parts, m.portsModel.table.FilterBar().View())
	case m.activeTab == tabDiagnostics && !m.inTrace() && m.filterBar.IsVisible():
		parts = append(parts, m.filterBar.View())
	case m.activeTab == tabInterfaces && m.interfacesModel.table.FilterBar().IsVisible():
		parts = append(parts, m.interfacesModel.table.FilterBar().View())
	case m.activeTab == tabForward && m.forwardModel.table.FilterBar().IsVisible():
		parts = append(parts, m.forwardModel.table.FilterBar().View())
	}

	tabs := theme.RenderTabs([]theme.TabItem{
		{Label: "Diagnostics"},
		{Label: "Ports"},
		{Label: "Interfaces"},
		{Label: "Forward"},
		{Label: "Path"},
	}, m.activeTab)
	tabBar := theme.PadWithBg(theme.Bg(" ")+tabs, width)

	// The message belongs to the tab that raised it: each sub-model keeps its
	// own, so switching away does not carry one tab's notice onto another.
	footer, status := m.activeFooter()
	parts = append(parts, tabBar, theme.EmptyLineBg(width), footer.View(width, status))
	return strings.Join(parts, "\n")
}

// activeFooter resolves the message line of whichever tab is on screen, and the
// status that tab derives on every frame.
func (m *Model) activeFooter() (*components.FooterMessage, components.Status) {
	switch m.activeTab {
	case tabPorts:
		return &m.portsModel.footer, m.portsModel.statusLine()
	case tabInterfaces:
		return &m.interfacesModel.footer, m.interfacesModel.statusLine()
	case tabForward:
		return &m.forwardModel.footer, m.forwardModel.status()
	case tabPath:
		return &m.pathModel.footer, m.pathModel.statusLine()
	}
	if m.state == StateTrace {
		return &m.pathModel.footer, m.pathModel.statusLine()
	}
	return &m.footer, m.statusLine()
}

// statusLine is what the diagnostics tab derives on every frame: a progress
// label while the pipeline walks, and nothing once it has an answer. It is a
// status rather than a footer message because it is a state, not an event —
// a message expires after three seconds and a run outlives that (Rule 128).
func (m *Model) statusLine() components.Status {
	if m.state == StateRunning {
		return components.Status{Text: m.progressLabel(), Activity: true}
	}
	if m.state == StateInput {
		if st := m.traceValidation.Status(); st.Text != "" {
			return st
		}
	}
	if m.state == StateInput {
		if a := m.traceable(); !a.Enabled() {
			return components.Status{Text: a.Reason, Level: components.LevelWarning}
		}
	}
	return components.Status{}
}

// GetHelpContent implements help.Provider
func (m *Model) GetHelpContent() help.Content {
	return help.Content{
		Title:       "Network",
		Description: "Five-tab view: check whether a host is reachable and its certificate chain sound (Diagnostics), monitor live ports (Ports), inspect this machine's network interfaces (Interfaces), or redirect a local port to a host:port, or give a service a name (Forward), or trace the hops a packet takes to a host (Path).",
		KeyBindings: []help.KeyBinding{
			// Tab navigation
			{Key: "tab / shift+tab", Description: "Cycle between the Diagnostics, Ports, Interfaces, Forward and Path tabs"},
			// Diagnostics
			{Key: "↑ / ↓", Description: "Navigate between the fields and the Run Diagnostics and Trace Path buttons (Diagnostics tab)"},
			{Key: "enter (form)", Description: "Run the checks against the target, from any field or the Run Diagnostics button"},
			{Key: "esc (running)", Description: "Cancel the run and keep what completed"},
			{Key: "enter (results)", Description: "Explain the selected check"},
			{Key: "p", Description: "Show problems only / show every check (Diagnostics tab)"},
			{Key: "/", Description: "Search checks by name or observation (Diagnostics tab)"},
			{Key: keymap.Diagnose + " (results)", Description: "Trace the path to the target: on the Local route row, opens the trace sub-level on the host, ready to start; nothing is sent until enter; greyed out on a platform that cannot trace or a target the trace refuses, with the reason in the footer (Diagnostics tab)"},
			{Key: "ctrl+r", Description: "Run the checks again"},
			{Key: "esc (results)", Description: "Back to the target form, or back to wherever this run was opened from (e.g. status's H) when it was opened prefilled"},
			{Key: keymap.New + " (results)", Description: "Start a new diagnostic — always resets to the form, even when esc there means \"go back\""},
			{Key: "esc (details)", Description: "Back to the checks"},
			{Key: "pgup / pgdown", Description: "Scroll half page up / down"},
			// Ports tab
			{Key: "t", Description: "Toggle TCP filter — cumulative with u (Ports tab)"},
			{Key: "u", Description: "Toggle UDP filter — cumulative with t (Ports tab)"},
			{Key: "l", Description: "Toggle LISTEN state filter — cumulative with e (Ports tab)"},
			{Key: "e", Description: "Toggle ESTAB state filter — cumulative with l (Ports tab)"},
			{Key: "n", Description: "Toggle numeric addresses / reverse-DNS host names (Ports tab)"},
			{Key: "z", Description: "Reset all active filters (Ports tab)"},
			{Key: "/", Description: "Search ports by address, process or PID (Ports tab)"},
			{Key: "space (Ports)", Description: "Pause / resume auto-refresh (Ports tab)"},
			{Key: keymap.Kill, Description: "Send SIGKILL to the selected process, after confirmation (Ports tab)"},
			// Interfaces tab
			{Key: "/", Description: "Search interfaces by name, MAC or address (Interfaces tab)"},
			{Key: ".", Description: "Cycle the sort column (Interfaces tab)"},
			{Key: "ctrl+r", Description: "Re-read the interfaces (Interfaces tab)"},
			// Forward tab
			{Key: keymap.New, Description: "Open a new forward — TCP, or a named HTTP route (Forward tab)"},
			{Key: "space", Description: "Pause the selected forward, or resume a paused or unbound one (Forward tab)"},
			{Key: keymap.Kill, Description: "Delete the selected forward, after confirmation (Forward tab)"},
			{Key: "/", Description: "Search forwards by port or target (Forward tab)"},
			{Key: ".", Description: "Cycle the sort column (Forward tab)"},
			// Path tab
			{Key: "enter (Path)", Description: "Trace the path to the target typed in the field, or trace again once a trace is done (Path tab)"},
			{Key: "esc (Path, running)", Description: "Cancel the trace and keep the hops already seen (Path tab)"},
			{Key: "esc (Path, done)", Description: "Edit the target again, keeping its value (Path tab)"},
			{Key: "enter (Trace Path button)", Description: "Trace the path to the form's target in a sub-level of the Diagnostics tab, Network › Path › target; Port and DNS Server are ignored by the trace (an info line says so); greyed out on a platform that cannot trace, with the reason in the footer (Diagnostics tab)"},
			{Key: "esc (trace)", Description: "Cancel a running trace; once it ended or before it started, go back to the form or the results it was opened from, with everything kept (Diagnostics tab)"},
			{Key: "↑ / ↓ / pgup / pgdown / home / end (trace)", Description: "Move in the hop table; every other key is ignored there except tab, which switches tab (Diagnostics tab)"},
			{Key: "enter (trace)", Description: "Start the trace, or trace again once it ended (Diagnostics tab)"},
			{Key: "ctrl+o (trace)", Description: "Choose where the trace starts: this machine or a running container; ↑↓ to move, enter to choose (it starts nothing), esc to close (Diagnostics tab)"},
			{Key: "ctrl+o (Path)", Description: "Choose where the trace starts: this machine or a running container; ↑↓ to move, enter to choose, esc to close (Path tab)"},
		},
		Sections: []help.Section{
			{
				Title: "Diagnostics Tab — What it asks",
				Body: "One target, one run. The checks follow from the target and from what has " +
					"already failed, so there is nothing to select.\n\n" +
					"DNS resolution     - the name, against the resolver your own traffic uses\n" +
					"Reverse DNS        - the name an address publishes (literal targets only)\n" +
					"Local route        - which interface carries this target, and from which address\n" +
					"ICMP echo          - reachability; a filtered echo is a warning, never a failure\n" +
					"TCP connect        - the port you named, and the answer that decides reachability\n" +
					"TLS handshake      - whether the port speaks TLS at all\n" +
					"Certificate chain  - verified against this machine's store, intermediates included\n" +
					"Hostname match     - whether the certificate names the host you dialled\n" +
					"Certificate expiry - the validity window, in days\n" +
					"TLS version        - the negotiated protocol version\n" +
					"HTTP response      - whether the service answers, over the scheme actually spoken",
			},
			{
				Title: "Diagnostics Tab — Reading the verdicts",
				Body: "OK      - the objective is met\n" +
					"WARN    - met, but something is off: a certificate near expiry, a deprecated\n" +
					"          version, a chain that verifies here and will not elsewhere\n" +
					"FAIL    - the objective is not met\n" +
					"N/A     - no meaning for this target, or blocked by a check above it\n" +
					"UNKNOWN - the check could not look, which is not the same as a pass\n\n" +
					"A stage whose dependency failed does not run: its checks come back N/A naming " +
					"what blocked them, so a broken run reads as one failure and a named point of " +
					"rupture rather than as ten red rows.\n\n" +
					"Press enter on any row for what it means and what to do about it.",
			},
			indicator.Legend(),
			{
				Title: "Ports Tab — How it works",
				Body: "Reads this machine's TCP and UDP sockets every 2 seconds, in this process — no " +
					"container, no Docker. Shows the owning process name and PID where the system will " +
					"name one. K terminates that process, after a confirmation, with the rights DevDesk " +
					"itself has: another user's process or a service comes back refused rather than " +
					"silently killed elsewhere.\n\n" +
					"n toggles reverse DNS on the addresses. Host names only — port numbers stay " +
					"numeric, because a service name would be DevDesk's guess and not the system's.\n\n" +
					"While K is killing a process, the dot on its sockets (" + indicator.Glyph(indicator.Running, true) +
					") is lit and the footer names the kill.",
			},
			{
				Title: "Forward Tab — How it works",
				Body: "Redirects traffic to a host:port, inside this process — no privilege, " +
					"no container, nothing written to a system file. Use it to reach a port nothing " +
					"published: a container's EXPOSEd port, or a service on another machine.\n\n" +
					"N opens a form with a Type field, changed with ← →. TCP redirects a local port " +
					"to a host:port. HTTP gives the target a name instead of a port: fill in Name " +
					"and Target, and http://<name>:<proxy port> reaches it.\n\n" +
					"A name must end in .localhost, such as api.localhost — nothing else is " +
					"accepted. That suffix is reserved for this machine, so it needs no DNS entry and " +
					"no privilege; any other name would not resolve. Every named route is served on " +
					"the same port, network.proxy_port (8080 by default, in the network tab of the " +
					"configuration), and the request's Host header picks the target — so " +
					"http://api.localhost:8080 and http://app.localhost:8080 are two services on one " +
					"port. The port stays in the URL because 80 is privileged. It is HTTP only: " +
					"https would need a certificate your browser trusts. A name that is not known " +
					"gets a page listing the ones that are.\n\n" +
					"Everything listens on 127.0.0.1 only, so it is available to this machine and " +
					"not to the network — a service kept off the LAN stays off it. A TCP forward's " +
					"local port has to be 1024 or above, and cannot be the proxy's: anything below " +
					"needs privileges DevDesk does not ask for, and there is no unprivileged way " +
					"around that on Linux or macOS.\n\n" +
					"The target is dialled once before the port is bound, so an address that answers " +
					"nothing is refused immediately instead of failing later at the first client. A " +
					"container's own address is reachable from the host on native Linux; under " +
					"Docker Desktop it lives in the virtual machine and does not route out of it.\n\n" +
					"Forwards are saved in ~/.devdesk/forwards.yaml and reopened when DevDesk " +
					"starts. They survive a context switch — a local port pointed at a host:port " +
					"belongs to no context — but the listener itself cannot outlive the process, so " +
					"what comes back is the list, bound again.\n\n" +
					"A forward that cannot be bound at launch — its port is taken, or its target is " +
					"not up yet — is not deleted. Its row reads unbound, the last error says why, and " +
					"space tries again. Space also pauses a live forward: the port is released and the " +
					"row stays, paused, until you resume it. K deletes a forward for good, and asks " +
					"first.",
			},
			{
				Title: "Path Tab — How it works",
				Body: "Traces the hops between this machine and a target, in this process — no " +
					"container, no traceroute binary. Native Linux and WSL2 only: on macOS, Windows and WSL1 the tab says so " +
					"and enter and ctrl+o are greyed out. IPv4 only: a host name is resolved to its IPv4 address. " +
					"The column starts on this machine: the interface the target's traffic leaves by, " +
					"with its source address, and the gateway, read from this machine's routing table, " +
					"then the hops. Under WSL2 the source row names the WSL2 VM, and in NAT mode the " +
					"first hop through the virtual switch is labelled Windows host.\n\n" +
					"Type a host name or an IPv4 address, and press enter; a port is refused because " +
					"the trace probes a host, not a service. Each hop is a UDP datagram sent to UDP " +
					"port 33435 with a growing time-to-live; the router that drops it answers, and the " +
					"table fills in as the answers come. No connection is made. Nothing is sent before you " +
					"press enter.\n\n" +
					"A silent hop is not a failure: many routers do not answer these probes, so the row " +
					"reads silent and the trace goes on. The header says how a trace ended.\n\n" +
					"When the target never answers, the silent hops at the end fold into one row, " +
					"no response beyond hop N, and the last hop that answered reads last to answer. " +
					"When this machine has no route to the target, the interface row reads no route " +
					"and nothing is sent; undetermined means the routing table could not be read, " +
					"which says nothing either way. DevDesk shows only what came back: it does not " +
					"say why the rest stayed silent.\n\n" +
					"ctrl+o opens Trace from: this machine, or a running container (Docker Engine on " +
					"Linux only). The column then starts with the container, its network and the " +
					"gateway it uses, and a row says the probes still leave from this machine: " +
					"nothing runs inside the container.\n\n" +
					"Docker Desktop and podman are not offered. With no running container, only this " +
					"machine is offered. Reading the engine (ps, info, inspect) starts nothing. An " +
					"engine reached through DOCKER_HOST or a remote context is not detected as remote: " +
					"it can show another machine's network, and the trace still leaves from this machine.\n\n" +
					"The bridge row appears only when this machine has the interface of the container's " +
					"network bridge, read on this machine; otherwise no bridge is shown. A remote engine " +
					"whose network is also called docker0 can match this machine's interface by name.\n\n" +
					"When the container's bridge is not on this machine, the engine row reads " +
					"internal path not visible (location unknown): the engine may run in a VM, remote " +
					"or rootless, and DevDesk does not guess. When it cannot check, the row reads " +
					"undetermined (bridge not verified). The hops are traced from this machine (the " +
					"host, or the WSL VM when DevDesk runs under WSL); DevDesk cannot see inside the " +
					"engine's VM.",
			},
			{
				Title: "Interfaces Tab — How it works",
				Body: "Lists this machine's network interfaces, read in this process — no container, " +
					"no Docker. Name, state, MTU, hardware address, error counters and every address " +
					"the interface carries. ctrl+r re-reads them.\n\n" +
					"A dash is not a zero. RX err and TX err show a dash when the counters could not " +
					"be read at all, which is a different thing from an interface that has dropped " +
					"nothing; MTU shows one where the platform reports no figure, as Windows does " +
					"for its loopback.\n\n" +
					"This was the Topology tab. Its routing table, ARP cache and firewall summary " +
					"were read by running ip and iptables in a container on the Docker Desktop VM, " +
					"so they described the VM and not this machine. Nothing portable produces them, " +
					"so they were removed rather than translated — and the route question moved to " +
					"the Diagnostics tab, where it is asked about a target: the Local route check " +
					"names the interface your traffic to that host actually leaves by.",
			},
			{
				Title: "Where the checks run",
				Body: "Everything here runs in this process, on this machine's network stack: the " +
					"diagnostic checks, the socket table, the interfaces and the path trace alike. They answer for " +
					"the resolver, the routing table, the sockets and the VPN you are actually on, " +
					"and nothing needs Docker.\n\n" +
					"The route trace used to be the exception. It ran traceroute in a container " +
					"started with --network host, which on Docker Desktop is the Linux VM's " +
					"namespace — so it traced the path from the VM and not from here, and the two " +
					"are not the same network. It was removed rather than kept with a caveat.\n\n" +
					"The trace is back, in this process: the Path tab sends its own probes from this " +
					"machine's network stack, so it answers for the network you are actually on. The " +
					"Local route check still names the interface and source address your traffic to a " +
					"target leaves by — the split-tunnel answer, read from this machine.",
			},
		},
	}
}

package netdiag

import (
	"log"

	"charm.land/bubbles/v2/textinput"
	tea "charm.land/bubbletea/v2"

	"github.com/anthnel/devdesk/internal/forward"
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/netcheck"
	"github.com/anthnel/devdesk/internal/shared"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/keymap"
)

// Init implements tea.Model
func (m *Model) Init() tea.Cmd {
	// The router runs Init on every entry. A source listing that came back while
	// another view was on screen went to that view, so a selector left open
	// would wait for it for good; it closes here instead.
	m.pathModel.closePicker()
	return tea.Batch(
		textinput.Blink,
		m.portsModel.initPorts(),
		m.interfacesModel.initInterfaces(),
		// The forwards live on the router, which broadcasts when they change.
		// A view built after the last change was not there for it, so it asks
		// once on the way in — the role sendJobsTo plays for the job registry.
		forward.Refresh,
	)
}

// Running reports whether a diagnostic is walking its stages now, which is what
// the router asks before it would rebuild the view: dropping it mid-run would
// discard the run without a word.
//
// A path trace counts too, even from another tab: it goes on there.
func (m *Model) Running() bool { return m.state == StateRunning || m.pathModel.running() }

// InEditMode implements FormView — true when a text input is active, so the
// router hands the key to the field rather than opening the command line.
func (m *Model) InEditMode() bool {
	if m.inTrace() {
		return m.pathModel.pickerOpen()
	}
	switch m.activeTab {
	case tabPorts:
		return m.portsModel.InEditMode()
	case tabInterfaces:
		// The interfaces table has a search box now, where the Topology tab it
		// replaced had no input at all. Returning false here would let a ":"
		// typed into the query open the command line instead (Rule 111).
		return m.interfacesModel.InEditMode()
	case tabForward:
		return m.forwardModel.InEditMode()
	case tabPath:
		return m.pathModel.InEditMode()
	}
	if m.filterBar.InEditMode() {
		return true
	}
	if m.state == StateInput {
		return m.focusedField == fieldTarget || m.focusedField == fieldPort || m.focusedField == fieldDNSServer
	}
	return false
}

// Update implements tea.Model
func (m *Model) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
	switch msg := msg.(type) {
	case tea.WindowSizeMsg:
		m.width = msg.Width
		m.height = msg.Height
		m.resizeInputs()
		m.filterBar.Resize(msg.Width)
		m.rebuildChecksTable()
		m.resizeDetailsViewport()
		m.portsModel.resize(msg.Width, msg.Height)
		m.interfacesModel.resize(msg.Width, msg.Height)
		m.forwardModel.resize(msg.Width, msg.Height)
		m.pathModel.resize(msg.Width, msg.Height)
		return m, nil

	// The router's animation frame: the blink phase of the Ports dot and of the
	// two footers that show the shared activity dot, whichever tab is on screen
	// so a tab never comes back with a frozen phase.
	case jobs.FrameMsg:
		m.portsModel.table.SetBlinkPhase(msg.Blink)
		m.footer.SetBlinkPhase(msg.Blink)
		m.interfacesModel.footer.SetBlinkPhase(msg.Blink)
		m.pathModel.footer.SetBlinkPhase(msg.Blink)
		return m, nil

	case stageDoneMsg:
		return m.handleStageDone(msg)

	// Ports sub-model messages.
	case portsTickMsg, portsDataMsg, portsKillResultMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// The terminal focus reaches the ports poll on every tab: its tick runs
	// whichever tab shows.
	case shared.TerminalFocusMsg:
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd

	// Two tabs now ask before they act — Ports before a kill (§3.26), Forward
	// before dropping the connections a redirection is carrying — so the answer
	// goes to the tab that asked rather than to Ports unconditionally, which
	// would have confirmed a kill from the Forward tab's modal.
	case components.ConfirmModalYesMsg, components.ConfirmModalNoMsg:
		return m.routeConfirm(msg)

	// Forward sub-model messages. ChangedMsg is the router's broadcast, and it
	// reaches this view wherever it stands, on screen or not.
	case forward.ChangedMsg, forwardTickMsg, ForwardFormSubmitMsg, ForwardFormCancelMsg:
		var cmd tea.Cmd
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd

	// Path sub-model messages: a trace goes on, and its hops keep arriving,
	// whichever tab is on screen.
	case pathResolvedMsg, pathHopMsg, pathDoneMsg, pathSourcesMsg:
		var cmd tea.Cmd
		m.pathModel, cmd = m.pathModel.update(msg)
		return m, cmd

	// Topology sub-model messages
	case ifaceDataMsg:
		var cmd tea.Cmd
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
		return m, cmd

	case tea.KeyPressMsg:
		return m.handleKey(msg)

	case tea.PasteMsg:
		return m.handlePaste(msg)
	}

	// Each tab holds its own footer, so an expiry has to be offered to all
	// five: the timer fires wherever the user has since navigated. The Path tab
	// also takes the cursor blink of its field.
	m.footer.Handle(msg)
	m.portsModel.footer.Handle(msg)
	m.interfacesModel.footer.Handle(msg)
	m.forwardModel.footer.Handle(msg)
	var cmd tea.Cmd
	m.pathModel, cmd = m.pathModel.update(msg)
	return m, cmd
}

// routeConfirm hands a confirmation answer to the tab that put the modal up.
func (m *Model) routeConfirm(msg tea.Msg) (*Model, tea.Cmd) {
	var cmd tea.Cmd
	if m.activeTab == tabForward {
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd
	}
	m.portsModel, cmd = m.portsModel.update(msg)
	return m, cmd
}

// handleStageDone records one stage's answers and starts the next.
func (m *Model) handleStageDone(msg stageDoneMsg) (*Model, tea.Cmd) {
	if msg.gen != m.runGen {
		return m, nil // a superseded run
	}
	m.results = msg.results
	m.rebuildChecksTable()

	steps := netcheck.Steps()
	if msg.next >= len(steps) {
		m.state = StateResults
		m.verdict = netcheck.Summarize(m.results.All())
		log.Printf("INFO [netdiag] run finished: verdict=%s over %d checks",
			m.verdict, len(m.results.All()))
		return m, nil
	}

	m.runStep = msg.next
	m.runStage = steps[msg.next]

	tg, err := m.buildTarget()
	if err != nil {
		// The form has not changed since the run started, so this cannot
		// normally fail. Reporting it beats continuing with a target nobody
		// can name.
		log.Printf("ERROR [netdiag] target became invalid mid-run: %v", err)
		m.state = StateResults
		return m, m.footer.Error("Run stopped — the target is no longer valid")
	}
	return m, runStageCmd(m.runGen, tg, m.checkSettings(), msg.next, m.results)
}

// handlePaste gives pasted text to the field that has the keyboard on the tab on
// screen. It never reaches the key handlers, so no action fires (Rule 111).
func (m *Model) handlePaste(msg tea.PasteMsg) (*Model, tea.Cmd) {
	var cmd tea.Cmd
	switch m.activeTab {
	case tabPorts:
		m.portsModel, cmd = m.portsModel.update(msg)
	case tabInterfaces:
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
	case tabForward:
		m.forwardModel, cmd = m.forwardModel.update(msg)
	case tabPath:
		m.pathModel, cmd = m.pathModel.update(msg)
	default:
		switch {
		case m.filterBar.InEditMode():
			m.filterBar, cmd = m.filterBar.Update(msg)
			m.rebuildChecksTable()
		case m.state == StateInput:
			return m.updateActiveInput(msg)
		}
	}
	return m, cmd
}

func (m *Model) handleKey(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	// A filter bar in edit mode claims every key before anything else, or a
	// query cannot contain the letters the view binds.
	if m.activeTab == tabDiagnostics && m.filterBar.InEditMode() {
		var cmd tea.Cmd
		m.filterBar, cmd = m.filterBar.Update(msg)
		m.rebuildChecksTable()
		return m, cmd
	}

	// An open selector holds every key, tab included: it is a mode.
	if (m.activeTab == tabPath || m.inTrace()) && m.pathModel.pickerOpen() {
		var cmd tea.Cmd
		m.pathModel, cmd = m.pathModel.update(msg)
		return m, cmd
	}

	// Tab / Shift+Tab cycles between the tabs (Rule 135)
	switch msg.String() {
	case "tab":
		m.activeTab = (m.activeTab + 1) % tabCount
		return m, nil
	case "shift+tab":
		m.activeTab = (m.activeTab + tabCount - 1) % tabCount
		return m, nil
	}

	// Route to active tab
	if m.activeTab == tabPorts {
		var cmd tea.Cmd
		m.portsModel, cmd = m.portsModel.update(msg)
		return m, cmd
	}
	if m.activeTab == tabInterfaces {
		var cmd tea.Cmd
		m.interfacesModel, cmd = m.interfacesModel.update(msg)
		return m, cmd
	}
	if m.activeTab == tabForward {
		var cmd tea.Cmd
		m.forwardModel, cmd = m.forwardModel.update(msg)
		return m, cmd
	}
	if m.activeTab == tabPath {
		var cmd tea.Cmd
		m.pathModel, cmd = m.pathModel.update(msg)
		return m, cmd
	}

	switch m.state {
	case StateInput:
		return m.handleKeyInput(msg)
	case StateRunning:
		return m.handleKeyRunning(msg)
	case StateResults:
		return m.handleKeyResults(msg)
	case StateDetails:
		return m.handleKeyDetails(msg)
	case StateTrace:
		return m.handleKeyTrace(msg)
	}
	return m, nil
}

// handleKeyRunning cancels the run. The stage in flight is awaited rather than
// interrupted — it is a network read that will time out on its own — and its
// result is discarded by the generation counter.
func (m *Model) handleKeyRunning(msg tea.KeyPressMsg) (*Model, tea.Cmd) {
	if msg.String() != "esc" {
		return m, nil
	}
	m.runGen++
	m.state = StateResults
	m.verdict = netcheck.Summarize(m.results.All())
	m.rebuildChecksTable()
	return m, m.footer.Warn("Run cancelled — showing what completed")

