168	// GetHeaderInfo implements HeaderView.
169	//
170	// The verdict is the one line worth spending: it is the answer to the question
171	// the view exists for, and reading it off ten rows is what the header is
172	// supposed to save. It appears only once there is a run to summarise.
173	func (m *Model) GetHeaderInfo(context string) []shortcut.HeaderInfo {
174		info := []shortcut.HeaderInfo{
175			{Key: "Context", Value: context, Style: theme.HeaderValueStyle},
176		}
177		if m.activeTab == tabPath {
178			return append(info, m.pathModel.headerInfo()...)
179		}
180		if m.activeTab == tabInterfaces {
181			return append(info, shortcut.HeaderInfo{
182				Key:   "Interfaces",
183				Value: m.interfacesModel.summaryLine(),
184				Style: theme.HeaderValueStyle,
185			})
186		}
187		if m.activeTab == tabPorts {
188			return append(info, shortcut.HeaderInfo{
189				Key:   "Ports",
190				Value: m.portsModel.summaryLine(),
191				Style: theme.HeaderValueStyle,
192			})
193		}
194		if m.activeTab == tabForward {
195			return append(info, shortcut.HeaderInfo{
196				Key:   "Forwards",
197				Value: m.forwardModel.summaryLine(),
198				Style: theme.HeaderValueStyle,
199			})
200		}
201		if m.state == StateTrace {
202			return append(info, m.pathModel.headerInfo()...)
203		}
204		if m.activeTab != tabDiagnostics || m.state == StateInput {
205			return info
206		}
207		if len(m.results.All()) == 0 {
208			return info
209		}
210		return append(info, shortcut.HeaderInfo{
211			Key:   "Verdict",
212			Value: m.verdict.String(),
213			Style: verdictHeaderStyle(m.verdict),
214		})
215	}
