293	// activeFooter resolves the message line of whichever tab is on screen, and the
294	// status that tab derives on every frame.
295	func (m *Model) activeFooter() (*components.FooterMessage, components.Status) {
296		switch m.activeTab {
297		case tabPorts:
298			return &m.portsModel.footer, m.portsModel.statusLine()
299		case tabInterfaces:
300			return &m.interfacesModel.footer, m.interfacesModel.statusLine()
301		case tabForward:
302			return &m.forwardModel.footer, m.forwardModel.status()
303		case tabPath:
304			return &m.pathModel.footer, m.pathModel.statusLine()
305		}
306		if m.state == StateTrace {
307			return &m.pathModel.footer, m.pathModel.statusLine()
308		}
309		return &m.footer, m.statusLine()
310	}
