312	// statusLine is what the diagnostics tab derives on every frame: a progress
313	// label while the pipeline walks, and nothing once it has an answer. It is a
314	// status rather than a footer message because it is a state, not an event —
315	// a message expires after three seconds and a run outlives that (Rule 128).
316	func (m *Model) statusLine() components.Status {
317		if m.state == StateRunning {
318			return components.Status{Text: m.progressLabel(), Activity: true}
319		}
320		if m.state == StateInput {
321			if st := m.traceValidation.Status(); st.Text != "" {
322				return st
323			}
324		}
325		if m.state == StateInput {
326			if a := m.traceable(); !a.Enabled() {
327				return components.Status{Text: a.Reason, Level: components.LevelWarning}
328			}
329		}
330		return components.Status{}
331	}
